input.sparql:
PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?point ?tsid WHERE {
  ?point a brick:Electric_Power_Sensor ;
         brick:isPointOf ?zone ;
         ref:hasExternalReference ?ext ;
         ?ext ref:hasTimeseriesId ?tsid
  FILTER (?zone a brick:Zone)
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?point ?tsid ?unit WHERE {
  ?point brick:hasQuantityKind <http://qudt.org/vocab/quantitykind/ElectricPower> ;
         ref:hasExternalReference ?ext ;
         ?ext ref:hasTimeseriesId ?tsid
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?point ?p ?o WHERE {
  ?point a brick:Electric_Power_Sensor .
  ?point ?p ?o .
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?s ?p ?o WHERE {
  ?s a brick:Lighting .
}
